/**
 * GENERATED by the splash cutter from assets/app-icons/<theme>.png — do not edit by hand.
 * Each theme icon, keyed off its flat background and cut into layers:
 * `art` (what stands above the pages, pops up), `bookLeft`/`bookRight`
 * (the open book, split at the spine), `side` (larger separate pieces) and
 * `spark` (small ones: stars, petals, snowflakes, bats). Coordinates are on
 * the 1024×1024 icon. Drawn in this order: side, art, book, sparks.
 */
import type { ImageSourcePropType } from "react-native";
import type { ThemedEditionId } from "../../theme/atmospheres";

export type SplashLayerKind = "art" | "bookLeft" | "bookRight" | "side" | "spark";
export type SplashLayer = { kind: SplashLayerKind; x: number; y: number; w: number; h: number; source: ImageSourcePropType };
export type SplashScene = {
  /** The icon's own background — the whole screen takes it. */
  bg: string;
  /** Light background: the wordmark switches to dark ink. */
  light: boolean;
  /** "open": the book unfolds from the spine. "rise": a stack of books, which rises instead. */
  mode: "open" | "rise";
  /** Where the pages begin; the art pops up from this line. */
  bookTop: number;
  layers: SplashLayer[];
};

